// Requer NODE_FUNCTION_ALLOW_BUILTIN=crypto e JARVIS_EVENTS_SECRET no ambiente do n8n.
const crypto = require('crypto');
const body = JSON.stringify({
  event_id: crypto.randomUUID(),
  event_type: 'project.alert',
  schema_version: '1.0',
  source: 'n8n',
  project_id: 'flydelivery',
  workflow_id: $workflow.id,
  execution_id: $execution.id,
  occurred_at: new Date().toISOString(),
  payload: { severity: 'warning', title: 'Integração com erro', message: 'Exemplo de alerta enviado pelo n8n' }
});
const ts = String(Math.floor(Date.now() / 1000));
const sig = 'sha256=' + crypto.createHmac('sha256', $env.JARVIS_EVENTS_SECRET).update(ts + '.' + body).digest('hex');
return [{ json: { body, ts, sig } }];
